import{_ as o,C as s,o as a,c as l,j as t,a as r,b as c,w as n,E as h,a3 as d,O as p}from"./chunks/framework.4XV3vnnU.js";const v=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/architecture.md","filePath":"documentation/architecture.md","lastUpdated":1793117788000}'),u={name:"documentation/architecture.md"};function g(m,e,f,b,A,P){const i=s("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t("h1",{id:"architecture",tabindex:"-1"},[r("Architecture "),t("a",{class:"header-anchor",href:"#architecture","aria-label":'Permalink to "Architecture"'},"​")],-1)),e[2]||(e[2]=t("p",null,"Naira consists of a catalog service, a set of plugins running next to it, a UI and a portal shell. Authentication is delegated to Keycloak. All of it is installed with one Helm chart into a Kubernetes cluster, next to the systems the plugins read from.",-1)),(a(),c(d,null,{default:n(()=>[h(i,{id:"mermaid-6",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20sources%5B%22External%20systems%22%5D%0A%20%20%20%20%20%20%20%20LT%5B%22LiteLLM%22%5D%0A%20%20%20%20%20%20%20%20ML%5B%22MLflow%22%5D%0A%20%20%20%20%20%20%20%20OM%5B%22OpenMetadata%22%5D%0A%20%20%20%20%20%20%20%20K8S%5B%22Kubernetes%20API%22%5D%0A%20%20%20%20%20%20%20%20GH%5B%22GitHub%22%5D%0A%20%20%20%20%20%20%20%20MCP%5B%22MCP%20servers%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20pod%5B%22Catalog%20pod%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20CAT%5B%22Catalog%20service%3Cbr%2F%3EHTTP%20API%2C%20scheduler%2C%20store%22%5D%0A%20%20%20%20%20%20%20%20P1%5B%22plugin%20sidecar%22%5D%0A%20%20%20%20%20%20%20%20P2%5B%22plugin%20sidecar%22%5D%0A%20%20%20%20%20%20%20%20P3%5B%22plugin%20sidecar%22%5D%0A%20%20%20%20%20%20%20%20CAT%20--%20%22gRPC%20Collect%22%20--%3E%20P1%0A%20%20%20%20%20%20%20%20CAT%20--%20%22gRPC%20Collect%22%20--%3E%20P2%0A%20%20%20%20%20%20%20%20CAT%20--%20%22gRPC%20Collect%22%20--%3E%20P3%0A%20%20%20%20end%0A%0A%20%20%20%20sources%20--%3E%20P1%20%26%20P2%20%26%20P3%0A%0A%20%20%20%20UI%5B%22UI%3Cbr%2F%3EReact%22%5D%20--%20%22%2Fv1%2F*%22%20--%3E%20CAT%0A%20%20%20%20PORTAL%5B%22Portal%3Cbr%2F%3EOpenMFP%22%5D%20--%3E%20UI%0A%20%20%20%20KC%5B%22Keycloak%22%5D%20-.%20%22OIDC%20login%2C%3Cbr%2F%3Etoken%20verification%22%20.-%3E%20PORTAL%20%26%20CAT%0A%20%20%20%20PROM%5B%22Prometheus%22%5D%20--%20%22%2Fprometheus%2F*%22%20--%3E%20UI%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=p('<h2 id="catalog-service" tabindex="-1">Catalog service <a class="header-anchor" href="#catalog-service" aria-label="Permalink to &quot;Catalog service&quot;">​</a></h2><p>The catalog is a Go service with a Chi HTTP router. It owns the graph of nodes and relations, exposes it through the <a href="/pr-preview/pr-12/documentation/api">Catalog API</a> and manages the plugins:</p><ul><li>At startup it reads a plugin configuration file that lists every plugin with its gRPC address and an optional cron schedule, connects to each plugin and exits if one is unreachable.</li><li>A scheduler triggers plugin runs according to their cron expressions. Runs can also be started from the API and the portal.</li><li>Every run is recorded as an operation, modelled after the <a href="https://google.aip.dev/151" target="_blank" rel="noreferrer">AIP-151</a> long-running operation: it has a start and end time, a done flag, and either an error message or the number of nodes and relations it upserted.</li><li>A successful run replaces that plugin&#39;s previous snapshot in the store. See <a href="/pr-preview/pr-12/documentation/concepts#snapshots">Snapshots</a>.</li></ul><p>The store is in memory. The Helm chart already ships PostgreSQL, and persisting the graph there is in progress.</p><p>Every API request except the health check must carry a bearer token issued by Keycloak. The catalog verifies the token against the configured realm and accepts only tokens whose issuer matches its configuration.</p><h2 id="plugins-as-sidecars" tabindex="-1">Plugins as sidecars <a class="header-anchor" href="#plugins-as-sidecars" aria-label="Permalink to &quot;Plugins as sidecars&quot;">​</a></h2><p>Each plugin is its own container image. The chart runs the enabled plugins as native sidecars (init containers with a restart policy) in the catalog pod. They listen on loopback only, so nothing outside the pod can reach them, and the catalog connects to them over localhost.</p><p>The contract between catalog and plugin is one gRPC service with one RPC, <code>Collect</code>, which returns the nodes and relations the plugin currently sees. Plugins carry no state between runs. Configuration comes from environment variables, mounted config files and Secrets. Plugins that read the cluster get their own RBAC rules through the chart.</p><p>This design is recorded in <a href="https://github.com/naira-project/architecture/blob/main/adr/005-switch-to-grpc-sidecars.md" target="_blank" rel="noreferrer">ADR-005</a>. The plugin contract and how to implement it are described in <a href="/pr-preview/pr-12/documentation/plugin-authoring">Writing a Plugin</a>.</p><h2 id="ui-and-portal" tabindex="-1">UI and portal <a class="header-anchor" href="#ui-and-portal" aria-label="Permalink to &quot;UI and portal&quot;">​</a></h2><p>The UI is a React application that talks to the catalog API. It renders the overview, the catalogs, the detail pages, the Plugins page and the Tech Radar. It is served by nginx, which also proxies API calls to the catalog and, for the metric panels, proxies queries to a Prometheus-compatible endpoint with the user&#39;s token enforced.</p><p>The portal is an <a href="https://openmfp.org/" target="_blank" rel="noreferrer">OpenMFP</a> portal built on Luigi. It provides the shell: login through Keycloak, the left navigation and the frame in which the UI pages are shown as micro-frontends. Navigation entries are declared in the portal&#39;s service provider configuration, which is how new pages become visible. The UI can also be opened on its own during development.</p><p>Metric panels on inference endpoint pages are built with <a href="https://perses.dev/" target="_blank" rel="noreferrer">Perses</a> components and PromQL queries, following <a href="https://github.com/naira-project/architecture/blob/main/rfc/rfc-005-perses-embedded-dashboards.md" target="_blank" rel="noreferrer">RFC-005</a>.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>Keycloak is the identity provider. The portal performs the OIDC login and holds the session. The UI passes the user&#39;s access token on every request to the catalog and to the Prometheus proxy. The catalog validates tokens with Keycloak and rejects anything else.</p><p>Keycloak itself is not part of the Naira chart. In the local environment it comes from the test-dependencies chart, with a <code>naira</code> realm, a <code>naira-portal</code> client and a test user.</p><h2 id="deployment-layout" tabindex="-1">Deployment layout <a class="header-anchor" href="#deployment-layout" aria-label="Permalink to &quot;Deployment layout&quot;">​</a></h2><p>The Helm chart installs the catalog Deployment with its plugin sidecars, the UI, the portal, a PostgreSQL StatefulSet with a database seeding Job, and the ConfigMaps, Secrets, RBAC and NetworkPolicy they need. External systems are addressed by URL in the plugin configuration. The consolidation of all deployment paths into this chart is described in <a href="https://github.com/naira-project/architecture/blob/main/rfc/rfc-009-deployment-consolidation.md" target="_blank" rel="noreferrer">RFC-009</a>.</p><p>For development, a Tiltfile deploys the same chart with development values and the test-dependencies chart into a kind cluster. For CI, end-to-end scenarios deploy a scenario-specific subset of components into a fresh namespace and assert the resulting graph through the API.</p><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><p>Design discussions and decisions live in the <a href="https://github.com/naira-project/architecture" target="_blank" rel="noreferrer">architecture repository</a>:</p><ul><li><a href="https://github.com/naira-project/architecture/blob/main/rfc/rfc-004-core-api-v1-design.md" target="_blank" rel="noreferrer">RFC-004</a>: the design of the core API</li><li><a href="https://github.com/naira-project/architecture/blob/main/rfc/rfc-008-Kubernetes-Test-Environments-for-PR-Based-E2E-Testing.md" target="_blank" rel="noreferrer">RFC-008</a>: Kubernetes test environments for end-to-end testing</li><li><a href="https://github.com/naira-project/architecture/blob/main/rfc/rfc-010-plugin-ecosystem.md" target="_blank" rel="noreferrer">RFC-010</a>: the plugin ecosystem</li><li><a href="https://github.com/naira-project/architecture/blob/main/rfc/rfc-007-documentation-integration.md" target="_blank" rel="noreferrer">RFC-007</a>: documentation in context</li></ul>',22))])}const y=o(u,[["render",g]]);export{v as __pageData,y as default};
